<script setup>
import { computed,reactive } from 'vue';import { useRoute,useRouter } from 'vue-router';import StatusTag from '../components/StatusTag.vue';import { TASK_STATUS,getTaskById,updateApplicantSelection } from '../mock/tasks.js'
const route=useRoute();const router=useRouter();const advisorId='T001';const allowed=[TASK_STATUS.PUBLISHED,TASK_STATUS.SELECTING,TASK_STATUS.SELECTED,TASK_STATUS.LEADER_ASSIGNED,TASK_STATUS.IN_PROGRESS];const task=computed(()=>{const item=getTaskById(route.params.id);return item?.advisorId===advisorId&&allowed.includes(item.status)?item:null});const selections=reactive((task.value?.applicants||[]).map(item=>({studentId:item.studentId,selected:Boolean(item.selected||item.applyStatus==='selected'),selectionComment:item.selectionComment||''})));const selectedCount=computed(()=>selections.filter(item=>item.selected).length);function selectionOf(id){return selections.find(item=>item.studentId===id)}function save(){const result=updateApplicantSelection(task.value.taskId,selections.map(item=>({...item,applyStatus:item.selected?'selected':'not_selected'})));window.alert(result.message);if(result.success)router.push(`/teacher/tasks/${task.value.taskId}/applicants`)}function back(){router.push(`/teacher/tasks/${route.params.id}/applicants`)}
</script>
<template><main class="page"><div class="content"><template v-if="task"><header><div><p class="eyebrow">T104 · APPLICANT SELECTION</p><h1>报名学生筛选</h1><p>{{ task.title }} · 已选择 {{ selectedCount }} / {{ task.applicants.length }} 人</p></div><StatusTag :status="task.status" /></header><section class="panel"><div class="table-wrap"><table><thead><tr><th>最终参与</th><th>学生姓名</th><th>学号</th><th>学院</th><th>专业</th><th>筛选状态</th><th>筛选意见 / 未选中说明</th></tr></thead><tbody><tr v-for="item in task.applicants" :key="item.studentId"><td><input v-model="selectionOf(item.studentId).selected" type="checkbox" /></td><td>{{ item.studentName }}</td><td>{{ item.studentId }}</td><td>{{ item.college||'--' }}</td><td>{{ item.major||'--' }}</td><td><StatusTag :status="selectionOf(item.studentId).selected?'confirmed':'rejected'" :text="selectionOf(item.studentId).selected?'选中':'未选中'" /></td><td><input v-model="selectionOf(item.studentId).selectionComment" :placeholder="selectionOf(item.studentId).selected?'可填写选中意见':'可填写未选中说明'" /></td></tr><tr v-if="!task.applicants.length"><td class="empty" colspan="7">暂无报名学生，无法进行筛选。</td></tr></tbody></table></div></section><p class="hint">至少选中 1 名学生。保存后请继续指定队长。</p><div class="actions"><button class="back" @click="back">返回</button><button class="save" :disabled="!task.applicants.length" @click="save">保存筛选结果</button></div></template><section v-else class="panel empty">无权访问或任务状态不支持筛选。</section></div></main></template>
<style scoped>.page{min-height:100vh;padding:40px 24px;background:#f3f6fb}.content{width:min(100%,1200px);margin:auto}header{display:flex;justify-content:space-between;gap:20px;margin-bottom:20px}h1{margin:0}header p{color:#64748b}.eyebrow{margin:0 0 6px;color:#2563eb!important;font-size:12px;font-weight:800;letter-spacing:.12em}.panel{overflow:hidden;border:1px solid #e2e8f0;border-radius:14px;background:#fff}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse}th,td{padding:12px;border-bottom:1px solid #e2e8f0;text-align:left;white-space:nowrap}th{background:#f8fafc}td>input:not([type=checkbox]){min-width:240px;padding:9px;border:1px solid #cbd5e1;border-radius:8px;font:inherit}input[type=checkbox]{width:18px;height:18px;accent-color:#2563eb}.empty{padding:34px;text-align:center;color:#64748b}.hint{padding:13px;border-radius:9px;color:#475569;background:#e0f2fe}.actions{display:flex;justify-content:flex-end;gap:10px}.actions button{padding:10px 18px;border-radius:9px;font:inherit;font-weight:700;cursor:pointer}.back{border:1px solid #cbd5e1;background:#fff}.save{border:0;color:#fff;background:#2563eb}.save:disabled{opacity:.5}@media(max-width:650px){.page{padding:24px 14px}header{flex-direction:column}}</style>
